@charset "utf-8";

// Dimensions
$max-content-width: 800px;

@import
 "variables",
 "themes",
 "layout",
 "base",
 "distill",
 "cv",
 "font-awesome/fontawesome",
 "font-awesome/brands",
 "font-awesome/solid",
 "font-awesome/regular",
 "tabler-icons/tabler-icons.scss",
 "tabler-icons/tabler-icons-filled.scss",
 "tabler-icons/tabler-icons-outline.scss"
;
// Jure Leskovec-inspired academic pages
.jure-home {
 display: grid;
 grid-template-columns: 185px minmax(0, 1fr);
 gap: 2rem;
 font-family: Arial, Helvetica, sans-serif;
 font-size: 15px;
 line-height: 1.45;
 margin-top: 0.5rem;
}

.jure-sidebar {
 border-right: 1px solid var(--global-divider-color);
 padding-right: 1.25rem;
}

.jure-photo {
 border: 1px solid var(--global-divider-color);
 display: block;
 margin-bottom: 1rem;
 max-width: 155px;
 width: 100%;
}

.jure-nav {
 display: flex;
 flex-direction: column;
 gap: 0.28rem;
}

.jure-nav a {
 color: var(--global-theme-color);
 font-size: 0.95rem;
 text-decoration: none;
}

.jure-nav a.active {
 color: var(--global-text-color);
 font-weight: 700;
}

.jure-nav a:hover,
.jure-main a:hover {
 text-decoration: underline;
}

.jure-header {
 align-items: flex-start;
 border-bottom: 1px solid var(--global-divider-color);
 display: flex;
 gap: 1rem;
 justify-content: space-between;
 margin-bottom: 1.1rem;
 padding-bottom: 0.75rem;
}

.jure-header h1 {
 font-size: 2rem;
 font-weight: 700;
 line-height: 1.1;
 margin: 0;
}

.jure-header h1 span {
 color: var(--global-text-color-light);
 font-size: 1.4rem;
 font-weight: 400;
}

.jure-title {
 color: var(--global-text-color-light);
 margin: 0.35rem 0 0;
}

.jure-language {
 display: flex;
 gap: 0.35rem;
 white-space: nowrap;
}

.jure-page-language {
 justify-content: flex-end;
 margin-bottom: 0.6rem;
}

.jure-lang-toggle {
 background: transparent;
 border: 1px solid var(--global-divider-color);
 border-radius: 3px;
 color: var(--global-text-color);
 font-size: 0.78rem;
 padding: 0.15rem 0.5rem;
}

.jure-lang-toggle.active,
.jure-lang-toggle:hover {
 background: var(--global-theme-color);
 border-color: var(--global-theme-color);
 color: var(--global-bg-color);
}

.jure-lang-block {
 display: none;
}

.jure-lang-block.active {
 display: block;
}

.jure-section {
 margin-bottom: 1.25rem;
}

.jure-section h2 {
 border-bottom: 1px solid var(--global-divider-color);
 font-size: 1.35rem;
 font-weight: 700;
 margin: 0 0 0.55rem;
 padding-bottom: 0.2rem;
}

.jure-section h3 {
 font-size: 1.05rem;
 font-weight: 700;
 margin: 1rem 0 0.35rem;
}

.jure-section p {
 margin-bottom: 0.65rem;
}

.jure-section ul,
.jure-section ol {
 margin-bottom: 0;
 padding-left: 1.25rem;
}

.jure-section li {
 margin-bottom: 0.45rem;
}

.jure-publications ol {
 padding-left: 1.35rem;
}

.jure-publications li {
 margin-bottom: 0.55rem;
}

.jure-more {
 margin-top: 0.7rem;
}

.jure-section-link {
 float: right;
 font-size: 0.85rem;
 font-weight: 400;
 margin-top: 0.25rem;
}

.jure-main .publications {
 margin-top: 0.6rem;
}

@media (max-width: 768px) {
 .jure-home {
 grid-template-columns: 1fr;
 gap: 1rem;
 }

 .jure-sidebar {
 border-right: 0;
 border-bottom: 1px solid var(--global-divider-color);
 display: grid;
 gap: 1rem;
 grid-template-columns: 110px 1fr;
 padding: 0 0 1rem;
 }

 .jure-photo {
 margin-bottom: 0;
 max-width: 110px;
 }

 .jure-nav {
 align-content: start;
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 }

 .jure-header {
 flex-direction: column;
 }

 .jure-section-link {
 float: none;
 margin-left: 0.35rem;
 }
}
